/** Demo operation context containing named values and an externally supplied JDBC connection. */
public class Context {
    private final Map<String, Object> values = new HashMap<>();
    private Connection connection;

    public Object getValueAt(String name) {
        return values.get(Objects.requireNonNull(name, "Context field name"));
    }

    public void setValueAt(String name, Object value) {
        values.put(Objects.requireNonNull(name, "Context field name"), value);
    }

    /** The caller owns the connection and its transaction lifecycle. */
    public void setConnection(Connection connection) {
        this.connection = Objects.requireNonNull(connection, "JDBC connection");
    }

    public Connection getConnection() {
        if (connection == null) {
            throw new IllegalStateException("Configure a JDBC connection before executing a database step");
        }
        return connection;
    }
}

package com.ibm.il.dse.cc.decorator;

import com.ibm.dse.base.FormatDecoratorHolder;

/**
 * Sets xsi:nil="true" attribute when value is null or empty.
 * Implements Type 1 decorator contract (FormatDecoratorHolder).
 *
 * Format direction (addDecoration):   null/empty -> add xsi:nil="true" attribute
 * Unformat direction (removeDecoration): xsi:nil value -> return null
 */
public class NilDecorator extends FormatDecoratorHolder {

    /** Called during FORMAT. If value is null/empty, adds nil attribute. */
    @Override
    public String addDecoration(String value) {
        if (value == null || value.isBlank()) {
            // Signal to parent formatter to emit xsi:nil="true"
            return null;
        }
        return value;
    }

    /** Called during UNFORMAT (in reverse chain order). Null value -> empty string. */
    @Override
    public String removeDecoration(String value) {
        if (value == null) return "";
        return value;
    }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;

/**
 * String field formatter. Maps a single XML element to/from a context field.
 *
 * Attributes:
 *   dataName - the XML element name AND the context field name
 *
 * Any decorators that immediately follow this tag in the XML definition
 * are applied to the string value (addDecoration on format, removeDecoration
 * in reverse order on unformat).
 */
public class CCString extends AbstractFormatElement {

    private String dataName;

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName = tag.getAttribute("dataName");
    }

    /** format: reads context[dataName] -> applies decorators -> emits XML element */
    @Override
    public String format(Context ctx) throws Exception {
        String value = (String) ctx.getValueAt(dataName);
        value = applyDecorators(value);          // addDecoration chain (forward order)
        return "<" + dataName + ">" + value + "</" + dataName + ">";
    }

    /** unformat: reads XML element -> applies decorators in reverse -> writes context[dataName] */
    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        String value = extractElement(xml, dataName);
        value = removeDecorators(value);         // removeDecoration chain (reverse order)
        ctx.setValueAt(dataName, value);
    }

    private String applyDecorators(String v)  { throw new UnsupportedOperationException(); }
    private String removeDecorators(String v)  { throw new UnsupportedOperationException(); }
    private String extractElement(String xml, String name) { throw new UnsupportedOperationException(); }
}

