package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;

/**
 * XML container formatter. Groups child formatter tags into an XML element.
 *
 * Key attributes:
 *   dataName       - the XML element name
 *   transparent    - when "true", the wrapper element is NOT emitted on the wire;
 *                    child fields appear at the parent level
 *   unnamed        - controls whether dataName appears as the element name
 *
 * Any formatter type (including CCXML itself) can have decorators following it.
 */
public class CCXML extends AbstractFormatElement {

    private String  dataName;
    private boolean transparent = false;
    private boolean unnamed     = false;

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName    = tag.getAttribute("dataName");
        String t = tag.getAttribute("transparent");
        if ("true".equalsIgnoreCase(t)) this.transparent = true;
        String u = tag.getAttribute("unnamed");
        if ("true".equalsIgnoreCase(u)) this.unnamed = true;
        super.initializeFrom(tag);
    }

    @Override
    public String format(Context ctx) throws Exception {
        // If transparent=true, do not emit the wrapper element
        if (transparent) {
            return formatChildren(ctx);
        }
        return "<" + dataName + ">" + formatChildren(ctx) + "</" + dataName + ">";
    }

    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        // If transparent=true, parse children directly from the parent level
        if (transparent) {
            unformatChildren(xml, ctx);
        } else {
            String inner = extractElement(xml, dataName);
            unformatChildren(inner, ctx);
        }
    }

    private String formatChildren(Context ctx) throws Exception {
        throw new UnsupportedOperationException("Runtime method");
    }
    private void unformatChildren(String xml, Context ctx) throws Exception {
        throw new UnsupportedOperationException("Runtime method");
    }
    private String extractElement(String xml, String name) {
        throw new UnsupportedOperationException("Runtime method");
    }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;
import java.util.List;

/**
 * Index-based collection formatter. Iterates a List stored in the context
 * and applies child formatters to each element.
 *
 * Attributes:
 *   dataName - context field name holding the List, and the XML element wrapper
 *   times    - maximum iterations ("*" = unlimited)
 *
 * On format: iterates context[dataName] List, formats each item using child formatters.
 * On unformat: collects child XML blocks into a List, stores in context[dataName].
 *
 * Any formatter type can have decorators — including CCIColl itself.
 */
public class CCIColl extends AbstractFormatElement {

    private String dataName;
    private int    maxTimes = Integer.MAX_VALUE;

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName = tag.getAttribute("dataName");
        String times = tag.getAttribute("times");
        if (times != null && !"*".equals(times)) {
            this.maxTimes = Integer.parseInt(times);
        }
    }

    @Override
    public String format(Context ctx) throws Exception {
        List<?> items = (List<?>) ctx.getValueAt(dataName);
        if (items == null) return "";
        StringBuilder sb = new StringBuilder();
        int count = Math.min(items.size(), maxTimes);
        for (int i = 0; i < count; i++) {
            sb.append(formatItem(items.get(i), ctx, i));
        }
        return sb.toString();
    }

    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        // Parse repeated child elements into a List, store in context[dataName]
        throw new UnsupportedOperationException("Runtime method");
    }

    private String formatItem(Object item, Context ctx, int index) { throw new UnsupportedOperationException(); }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;

/**
 * Boolean field formatter. Maps "true"/"false" XML values to/from context.
 *
 * Attributes:
 *   dataName - the XML element name and context field name
 *   trueValue  - XML string representing true  (default: "true")
 *   falseValue - XML string representing false (default: "false")
 */
public class CCBoolean extends AbstractFormatElement {

    private String dataName;
    private String trueValue  = "true";
    private String falseValue = "false";

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName   = tag.getAttribute("dataName");
        String tv = tag.getAttribute("trueValue");
        if (tv != null) this.trueValue = tv;
        String fv = tag.getAttribute("falseValue");
        if (fv != null) this.falseValue = fv;
    }

    @Override
    public String format(Context ctx) throws Exception {
        Object val = ctx.getValueAt(dataName);
        boolean b = Boolean.TRUE.equals(val) || "true".equalsIgnoreCase(String.valueOf(val));
        return "<" + dataName + ">" + (b ? trueValue : falseValue) + "</" + dataName + ">";
    }

    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        String value = extractElement(xml, dataName);
        ctx.setValueAt(dataName, trueValue.equalsIgnoreCase(value));
    }

    private String extractElement(String xml, String name) { throw new UnsupportedOperationException(); }
}

package com.ibm.il.dse.cc.cut;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.DSEServerOperation;
import com.ibm.dse.base.KeyedCollection;
import com.ibm.dse.base.Tag;

import java.util.Hashtable;

/**
 * Base class for all WSBCC operations.
 * Loaded from XML via initializeFrom(Tag). Channel handler calls:
 *   1. unformat(requestXml)
 *   2. execute()
 *   3. format() -> returns response XML
 *
 * DO NOT instantiate directly. Defined as 'compound' in dse.ini operations section.
 */
public class CCDSEServerOperation extends DSEServerOperation {

    private static final int RC_TIMEOUT = -99;

    private String  operationName;
    private String  hostKey;
    private String  operationFields;
    private boolean writeToLog       = false;
    private boolean writeToOfecStat  = false;
    private boolean isSelectiveJournalising = false;

    private boolean returnedErrorBodyChanged = false;
    private String  returnedErrorBodyChanger = null;

    private Hashtable formats  = new Hashtable();

    /**
     * Main execution loop. Called by channel handler after unformat().
     * Runs the opStep chain according to RC routing attributes.
     */
    @Override
    public void execute() throws Exception {
        // Pre-populate context with operationFields (key=value pairs)
        if (operationFields != null && !operationFields.isBlank()) {
            setFields(operationFields);
        }

        // Remove opSteps that are not applicable to this channel (onlyFor filtering)
        removeOpStepsNotForThisChannel();

        // Run the opStep chain
        int index = 0;
        do {
            KeyedCollection kc = getOperationStep(index);
            index = processOpStep(kc, operationName, index);
        } while (index != -1);

        // Substitute error reply format if on{N}Return was triggered
        if (isReturnedErrorBodyChanged() && getReturnedErrorBodyChanger() != null) {
            // The channel handler reads csErrorReplyFormat instead of csReplyFormat
            substituteErrorReplyFormat();
        }
    }

    /**
     * Routes from one opStep to the next based on the return code.
     * Priority order:
     *   1. on{N}Return  -- switch error reply format body before routing
     *   2. onTimeoutDo  -- if RC == RC_TIMEOUT
     *   3. on{N}Do      -- exact RC match
     *   4. onOtherDo    -- default when no on{N}Do matches
     *   5. onOtherDoDefault -- final fallback (logs warning)
     */
    private int processOpStep(KeyedCollection kc, String opName, int currentIndex) {
        // Implementation provided by WAS runtime
        throw new UnsupportedOperationException("Runtime method");
    }

    private void removeOpStepsNotForThisChannel() {
        // Reads onlyFor attribute on each opStep; removes non-matching steps
        throw new UnsupportedOperationException("Runtime method");
    }

    private void setFields(String operationFields) {
        // Parses "KEY=VALUE,KEY2=VALUE2" and sets each in context
        throw new UnsupportedOperationException("Runtime method");
    }

    private void substituteErrorReplyFormat() {
        throw new UnsupportedOperationException("Runtime method");
    }

    public boolean isReturnedErrorBodyChanged()  { return returnedErrorBodyChanged; }
    public String  getReturnedErrorBodyChanger() { return returnedErrorBodyChanger; }
    public Hashtable getFormats()                { return formats; }
    public String getHostKey()                   { return hostKey; }
    public void setHostKey(String v)             { this.hostKey = v; }
    public String getOperationFields()           { return operationFields; }
    public void setOperationFields(String v)     { this.operationFields = v; }
    public boolean isWriteToLog()                { return writeToLog; }
    public void setWriteToLog(boolean v)         { this.writeToLog = v; }
}

package com.ibm.il.dse.cc.decorator;

import com.ibm.dse.base.FormatDecoratorHolder;
import com.ibm.dse.base.Tag;

/**
 * Pads a string to a fixed length using a specified pad character.
 *
 * Attributes:
 *   padChar  - character to use for padding (default '0')
 *   length   - target length after padding
 *   padLeft  - "true" to pad on left (default), "false" to pad on right
 *
 * Format direction (addDecoration):    pad value to target length
 * Unformat direction (removeDecoration): strip the padding characters
 *
 * Decorator chain example with two decorators:
 *   <CCString dataName="AccountNumber"/>
 *   <RemoveLeadingZerosDecorator/>
 *   <CCPadding padChar="0" length="10"/>
 *
 *   format:   "12345" -> RemoveLeadingZeros.add (no-op) -> CCPadding.add -> "0000012345"
 *   unformat: "0000012345" -> CCPadding.remove -> "12345" -> RemoveLeadingZeros.remove -> "12345"
 */
public class CCPadding extends FormatDecoratorHolder {

    private char    padChar = '0';
    private int     length  = 0;
    private boolean padLeft = true;

    @Override
    public Object initializeFrom(Tag tag) {
        String pc = tag.getAttribute("padChar");
        if (pc != null && !pc.isBlank()) this.padChar = pc.charAt(0);
        String len = tag.getAttribute("length");
        if (len != null) this.length = Integer.parseInt(len.trim());
        String pl = tag.getAttribute("padLeft");
        if ("false".equalsIgnoreCase(pl)) this.padLeft = false;
        return this;
    }

    @Override
    public String addDecoration(String value) {
        if (value == null) value = "";
        if (value.length() >= length) return value;
        String pad = String.valueOf(padChar).repeat(length - value.length());
        return padLeft ? pad + value : value + pad;
    }

    @Override
    public String removeDecoration(String value) {
        if (value == null) return null;
        if (padLeft) {
            return value.replaceFirst("^[" + java.util.regex.Pattern.quote(String.valueOf(padChar)) + "]+", "");
        } else {
            return value.replaceFirst("[" + java.util.regex.Pattern.quote(String.valueOf(padChar)) + "]+$", "");
        }
    }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

/**
 * Database lookup formatter. Queries a DB table during the FORMAT process.
 *
 * IMPORTANT for migration: This is a DB call embedded inside a format definition.
 * In the converted service, this lookup MUST be moved to the service layer.
 * The JAXB DTO must NOT contain this logic.
 *
 * Attributes:
 *   dataName    - XML element name
 *   fromTable   - DB table to query
 *   fromColumn  - column to retrieve
 *   keyValue    - context field name holding the lookup key
 */
public class CCTableFormat extends AbstractFormatElement {

    private String dataName;
    private String fromTable;
    private String fromColumn;
    private String keyValue;

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName   = tag.getAttribute("dataName");
        this.fromTable  = tag.getAttribute("fromTable");
        this.fromColumn = tag.getAttribute("fromColumn");
        this.keyValue   = tag.getAttribute("keyValue");
    }

    @Override
    public String format(Context ctx) throws Exception {
        // Reads key from context, queries DB, writes result as XML element
        String key = (String) ctx.getValueAt(keyValue);
        if (key == null) return "<" + dataName + "/>";

        Connection conn = ctx.getConnection();
        String sql = "SELECT " + fromColumn + " FROM " + fromTable + " WHERE KEY = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, key);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    String result = rs.getString(1);
                    result = applyDecorators(result);
                    return "<" + dataName + ">" + result + "</" + dataName + ">";
                }
            }
        }
        return "<" + dataName + "/>";
    }

    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        // CCTableFormat is output-only — typically not unformatted
        String value = extractElement(xml, dataName);
        if (value != null) ctx.setValueAt(dataName, value);
    }

    private String applyDecorators(String v) { throw new UnsupportedOperationException(); }
    private String extractElement(String x, String n) { throw new UnsupportedOperationException(); }
}

